import * as net from 'node:net';
function main(): void {
  let got = '';
  let left = 2;
  const finish = (): void => { if (--left === 0) console.log('client got', JSON.stringify(got)); };
  const server: any = net.createServer((sock: any): void => {
    sock.on('data', (d: any): void => { sock.write(d); sock.destroy(); server.close(); });
  });
  server.on('close', finish);
  server.listen(0, '127.0.0.1', (): void => {
    const port = server.address().port;
    const c: any = net.connect(port, '127.0.0.1', (): void => { c.write('hello'); });
    c.on('data', (d: any): void => { got += d.toString(); });
    c.on('close', finish);
  });
}
